# MR LEE — 9 image horizontal glide, 2 seconds per image, smooth endless loop.
# Works on Windows PowerShell 5.1. Only modifies homepage banner and adds 2 static assets.
# Keeps Firebase, logo, site redesign, and all links. No PowerShell reserved $HOME variable.
param([string]$WebsitePath = '')
$ErrorActionPreference = 'Stop'
try {
  $projectRoot = $null
  $locations = @()
  if ($WebsitePath) { $locations += $WebsitePath }
  $locations += $PSScriptRoot
  $locations += (Get-Location).Path
  $locations += 'C:\Users\Surface\Documents\tienghanmrlee.github.io'
  foreach ($candidate in $locations) {
    if ($candidate -and (Test-Path -LiteralPath (Join-Path $candidate 'index.html') -PathType Leaf)) {
      $projectRoot = (Resolve-Path -LiteralPath $candidate).Path
      break
    }
  }
  if (-not $projectRoot) { throw 'Khong tim thay index.html. Dat .ps1 cung thu muc website, hoac truyen -WebsitePath.' }
  $sourceIndex = Join-Path $projectRoot 'index.html'
  $imagesPath = Join-Path $projectRoot 'images'
  $missingImages = @()
  foreach ($n in 1..9) {
    $image = Join-Path $imagesPath ($n.ToString() + '.png')
    if (-not (Test-Path -LiteralPath $image -PathType Leaf)) { $missingImages += ('images/' + $n + '.png') }
  }
  if ($missingImages.Count -gt 0) { throw ('Thieu anh: ' + ($missingImages -join ', ') + '. Khong thay doi website.') }

  $utf8 = New-Object System.Text.UTF8Encoding($false)
  $pageHtml = [System.IO.File]::ReadAllText($sourceIndex, [System.Text.Encoding]::UTF8)
  if ($pageHtml -notmatch '(?i)</head\s*>' -or $pageHtml -notmatch '(?i)</body\s*>') {
    throw 'index.html thieu the </head> hoac </body>. Khong sua.'
  }
  # Remove the old fading-banner effect and its old JS interval to avoid conflicting timers.
  $pageHtml = [regex]::Replace($pageHtml, '(?is)\s*<!--\s*MRLEE-BANNER9-CSS(?:-V\d+)?\s*-->\s*<style\b[^>]*>.*?</style\s*>', '')
  $pageHtml = [regex]::Replace($pageHtml, '(?is)\s*<!--\s*MRLEE-BANNER9-JS(?:-V\d+)?\s*-->\s*<script\b[^>]*>.*?</script\s*>', '')
  # Reinstall safely: remove previous slide-asset link/script tags, without touching others.
  $pageHtml = [regex]::Replace($pageHtml, '(?is)\s*<link\b(?=[^>]*\bhref\s*=\s*["'']mrlee-slide\.css(?:\?[^"'']*)?["''])[^>]*>', '')
  $pageHtml = [regex]::Replace($pageHtml, '(?is)\s*<script\b(?=[^>]*\bsrc\s*=\s*["'']mrlee-slide\.js(?:\?[^"'']*)?["''])[^>]*>\s*</script\s*>', '')

  if ($pageHtml -match '(?i)id\s*=\s*["'']mrleeBanner9["'']') {
    # Preserve all nine existing image links and their layout markup.
    if (([regex]::Matches($pageHtml, '(?is)<a\b[^>]*class\s*=\s*["''][^"'']*\bmrlee-banner9-slide\b')).Count -ne 9) {
      throw 'Tim thay banner cu nhung khong du 9 anh slide. Khong sua de tranh mat du lieu.'
    }
  } else {
    # For sites where older installers never installed the 9 banners: create it once.
    $open = [regex]::Match($pageHtml, '(?is)<div\b[^>]*\bclass\s*=\s*["''][^"'']*\bhero-banner\b[^"'']*["''][^>]*>')
    if (-not $open.Success) { throw 'Khong tim thay .hero-banner tren trang chu. Khong sua.' }
    $contentStart = $open.Index + $open.Length
    $nestedDivs = [regex]::Matches($pageHtml.Substring($contentStart), '(?is)</?div\b[^>]*>')
    $depth = 1
    $contentEnd = -1
    foreach ($tag in $nestedDivs) {
      if ($tag.Value -match '(?i)^</div') { $depth-- } else { $depth++ }
      if ($depth -eq 0) { $contentEnd = $contentStart + $tag.Index; break }
    }
    if ($contentEnd -lt $contentStart) { throw 'Khong xac dinh duoc cuoi .hero-banner. Khong sua.' }
    $targetLinks = @('bai-hoc.html','giao-tiep-theo-chu-de.html','on-luyen-phong-van.html','kiem-tra-dau-vao.html','kiem-tra-online.html','de-thi-topik.html','thi-topik-online.html','bo-sach.html','dang-nhap.html')
    $slideLines = New-Object 'System.Collections.Generic.List[string]'
    $slideLines.Add('<!-- MRLEE-BANNER9-START -->')
    $slideLines.Add('<div id="mrleeBanner9" class="mrlee-banner9" role="region" aria-roledescription="carousel" aria-label="9 anh bia hoc tap">')
    for ($i = 0; $i -lt 9; $i++) {
      $num = $i + 1
      $slideLines.Add(('<a class="mrlee-banner9-slide" href="{0}"><img src="images/{1}.png" alt="Noi dung hoc tap {1}" loading="{2}" decoding="async"></a>' -f $targetLinks[$i],$num,$(if ($i -eq 0) { 'eager' } else { 'lazy' })))
    }
    $slideLines.Add('</div>')
    $slideLines.Add('<!-- MRLEE-BANNER9-END -->')
    $slidesMarkup = [string]::Join("`n", $slideLines.ToArray())
    $pageHtml = $pageHtml.Substring(0,$contentStart) + "`n" + $slidesMarkup + "`n" + $pageHtml.Substring($contentEnd)
  }

  $stylesheet = '<link rel="stylesheet" href="mrlee-slide.css?v=20261010-slide2" data-mrlee-slide="css">'
  $javascript = '<script defer src="mrlee-slide.js?v=20261010-slide2" data-mrlee-slide="js"></script>'
  $pageHtml = [regex]::Replace($pageHtml, '(?i)</head\s*>', ($stylesheet + "`r`n</head>"))
  $pageHtml = [regex]::Replace($pageHtml, '(?i)</body\s*>', ($javascript + "`r`n</body>"))
  if (([regex]::Matches($pageHtml, 'id\s*=\s*["'']mrleeBanner9["'']')).Count -ne 1 -or
      ( [regex]::Matches($pageHtml, 'mrlee-slide\.js\?v=20261010-slide2') ).Count -ne 1 -or
      ( [regex]::Matches($pageHtml, 'mrlee-slide\.css\?v=20261010-slide2') ).Count -ne 1) {
    throw 'Kiem tra HTML that bai. Khong ghi de.'
  }

  $parent = Split-Path -Path $projectRoot -Parent
  $backupRoot = Join-Path $parent 'MRLEE-SAO-LUU-SLIDE'
  $backupFolder = Join-Path $backupRoot (Get-Date -Format 'yyyyMMdd-HHmmss-fff')
  New-Item -Path $backupFolder -ItemType Directory -Force | Out-Null
  $cssFile = Join-Path $projectRoot 'mrlee-slide.css'
  $jsFile = Join-Path $projectRoot 'mrlee-slide.js'
  foreach ($oldFile in @($sourceIndex, $cssFile, $jsFile)) {
    if (Test-Path -LiteralPath $oldFile) {
      Copy-Item -LiteralPath $oldFile -Destination (Join-Path $backupFolder (Split-Path $oldFile -Leaf)) -Force
    }
  }
  $cssBytes = [Convert]::FromBase64String('')
  $jsBytes = [Convert]::FromBase64String('')
  try {
    [System.IO.File]::WriteAllBytes($cssFile, $cssBytes)
    [System.IO.File]::WriteAllBytes($jsFile, $jsBytes)
    [System.IO.File]::WriteAllText($sourceIndex, $pageHtml, $utf8)
  } catch {
    foreach ($fileName in @('index.html','mrlee-slide.css','mrlee-slide.js')) {
      $saved = Join-Path $backupFolder $fileName
      if (Test-Path -LiteralPath $saved) { Copy-Item -LiteralPath $saved -Destination (Join-Path $projectRoot $fileName) -Force }
    }
    throw
  }
  Write-Host ''
  Write-Host 'SUCCESS: 9 anh truot ngang MUOT — moi 2 giay, hieu ung 900ms.' -ForegroundColor Green
  Write-Host 'Ho tro vuot tren dien thoai, nut trai/phai, tam dung/tiep tuc.' -ForegroundColor Cyan
  Write-Host ('Website: ' + $projectRoot)
  Write-Host ('Da sao luu: ' + $backupFolder) -ForegroundColor Yellow
  Write-Host 'Git: git add index.html mrlee-slide.css mrlee-slide.js; git commit -m "Smooth banner slideshow"; git push origin main'
} catch {
  Write-Host ('ERROR: ' + $_.Exception.Message) -ForegroundColor Red
  exit 1
}
